export function getTenetErrorMessage(code: TenetError): string {
  if (process.env['NODE_ENV'] !== 'production') {
    return (tenetErrorMessages as Record<TenetError, string>)[code];
  }

  return 'Error message not available in production bundles.';
}

export function isTenetError<TProgramErrorCode extends TenetError>(
    error: unknown,
    transactionMessage: { instructions: Record<number, { programAddress: Address }> },
    code?: TProgramErrorCode,
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> & Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(error, transactionMessage, TENET_PROGRAM_ADDRESS, code);
}